// 1. Get the raw data from the node
const rawData = {{node:get_node_PuLZdLqa.data.data.payload}};

// 2. Parse the string into an actual array
// Expected format: '["201355...", "201356..."]'
const dataArray = JSON.parse(rawData);

// 3. Return the full list
// We verify it is an array to be safe; otherwise return empty list []
const ids = Array.isArray(dataArray) ? dataArray : [];

return {
  ids: ids
};

const source = {{node:search_node_EYKVZtEy.data.data}};
const materials = Array.isArray(source) ? source : (source ? [source] : []);
const sets = {
 categoryIds: new Set(), uomIds: new Set(), taxIds: new Set(), tariffIds: new Set(),
 customerIds: new Set(), supplierIds: new Set(), priceTagIds: new Set()
};
const add = (key, value) => { if (value !== null && value !== undefined && value !== '') sets[key].add(String(value)); };
const activeRows = value => {
 let list = value;
 if (typeof list === 'string') { try { list = JSON.parse(list); } catch (error) { list = []; } }
 return (Array.isArray(list) ? list : []).filter(row => row && Number(row.is_deleted || 0) !== 1);
};
for (const item of materials) {
 add('categoryIds', item.item_category);
 for (const value of [item.based_uom, item.purchase_default_uom, item.sales_default_uom]) add('uomIds', value);
 for (const row of (Array.isArray(item.table_uom_conversion) ? item.table_uom_conversion : [])) {
  if (Number(row.is_deleted || 0) !== 1) add('uomIds', row.alt_uom_id);
 }
 for (const value of [item.mat_purchase_tax_id, item.mat_sales_tax_id]) add('taxIds', value);
 for (const value of [item.purchase_tariff_id, item.sales_tariff_id]) add('tariffIds', value);
 // Customer / supplier price rows: party, price tag and UOM (SQL price rows have no currency field).
 for (const row of activeRows(item.table_customer_price)) {
  add('customerIds', row.customer_id);
  add('priceTagIds', row.cust_price_tag_id);
  add('uomIds', row.cust_price_uom);
 }
 for (const row of activeRows(item.table_supplier_price)) {
  add('supplierIds', row.supplier_id);
  add('priceTagIds', row.sup_price_tag_id);
  add('uomIds', row.sup_price_uom);
 }
}
const result = {};
for (const [key, values] of Object.entries(sets)) {
 if (values.size > 100) throw new Error('Too many item references; select fewer items');
 result[key] = Array.from(values);
}
return result;

// SQL_FETCH_POST_DATA: item branch only. Optional fields are omitted, never zero-filled.
const materials = rows({{node:search_node_EYKVZtEy.data.data}});
const categories = rows({{node:search_node_Yg1yO16t.data.data}});
const uoms = rows({{node:search_node_RhXawYWY.data.data}});
const taxes = rows({{node:search_node_88m2dnyG.data.data}});
const tariffs = rows({{node:search_node_itemParityTariff.data.data}});
// Price-row lookups (1.2 Price Customer / Supplier / Tag):
const priceCustomers = rows({{node:search_node_dTEixn9g.data.data}});
const priceSuppliers = rows({{node:search_node_U6pSu9L4.data.data}});
const priceTags = rows({{node:search_node_3CYs0rat.data.data}});

function rows(value) {
  if (Array.isArray(value)) return value;
  if (value && Array.isArray(value.data)) return value.data;
  return value ? [value.data || value] : [];
}
const hasValue = value => value !== null && value !== undefined && value !== '';
const text = value => value == null ? '' : String(value);
const sanitize = value => text(value).replace(/"/g, '\u2033');
function numeric(value, field) {
  if (!hasValue(value)) return undefined;
  const n = Number(value);
  if (typeof value === 'boolean' || !text(value).trim() || !Number.isFinite(n)) throw new Error('Invalid ' + field);
  return n;
}
function flag(value, field) {
  if (!hasValue(value)) return undefined;
  if (value === true || value === 1 || value === '1') return true;
  if (value === false || value === 0 || value === '0') return false;
  throw new Error('Invalid ' + field);
}
function lookup(list, id, field, label) {
  if (!hasValue(id)) return undefined;
  const found = list.filter(row => text(row.id) === text(id) && Number(row.is_deleted || 0) !== 1);
  if (found.length !== 1 || !hasValue(found[0][field])) throw new Error('Unresolved or ambiguous ' + label);
  return text(found[0][field]);
}
function optional(target, key, value) { if (value !== undefined) target[key] = value; }
// ---- Customer / supplier price rows. SQL ST_ITEM_PRICE has no currency field: no currency is sent. ----
// PROPOSED payload contract: field names must be agreed with the agent DTO before publishing.
function activePriceRows(value) {
  let list = value;
  if (typeof list === 'string') { try { list = JSON.parse(list); } catch (error) { throw new Error('Invalid price table'); } }
  return (Array.isArray(list) ? list : []).filter(row => row && Number(row.is_deleted || 0) !== 1);
}
function discountText(value, type) {
  const n = numeric(value, 'price discount');
  if (n === undefined) return undefined;
  return type === '%' ? text(n) + '%' : text(n);
}
function dateText(value) { return hasValue(value) ? text(value) : undefined; }
function resolvePriceRow(row, customerSide) {
  const partyId = customerSide ? row.customer_id : row.supplier_id;
  const tagId = customerSide ? row.cust_price_tag_id : row.sup_price_tag_id;
  const p = customerSide ? 'cust' : 'sup';
  const account = customerSide
    ? lookup(priceCustomers, partyId, 'customer_id', 'price-row customer')
    : lookup(priceSuppliers, partyId, 'supplier_code', 'price-row supplier');
  const tag = lookup(priceTags, tagId, 'price_tag_code', 'price tag');
  if (!account && !tag) throw new Error('Price row needs a customer/supplier or a price tag');
  const uom = lookup(uoms, row[p + '_price_uom'], 'uom_name', 'price-row UOM');
  if (!uom) throw new Error('Price-row UOM is required');
  return {
    rowId: text(row.id), account, tag, uom,
    minQty: numeric(row[p + '_min_order_qty'], 'minimum order quantity'),
    maxQty: numeric(row[p + '_max_order_qty'], 'maximum order quantity'),
    price: numeric(row[p + '_price_unit_price'], 'unit price'),
    discount: discountText(row[p + '_price_discount'], row[p + '_price_discount_type']),
    dateFrom: dateText(row[p + '_price_date_from']),
    dateTo: dateText(row[p + '_price_date_to'])
  };
}

function barcode(value) {
  if (!hasValue(value)) return undefined;
  if (typeof value !== 'string') throw new Error('Barcode must be text to preserve leading zeros');
  return value;
}

return materials.map(material => {
  const base = lookup(uoms, material.based_uom, 'uom_name', 'base UOM');
  if (!base) throw new Error('Base UOM is required');
  const lines = rows(material.table_uom_conversion).filter(row => Number(row.is_deleted || 0) !== 1);
  const seen = new Set();
  const resolved = lines.map(row => {
    const name = lookup(uoms, row.alt_uom_id, 'uom_name', 'item UOM');
    if (!name) throw new Error('Item UOM is required');
    const key = name.toUpperCase();
    if (seen.has(key)) throw new Error('Duplicate item UOM');
    seen.add(key);
    return { row, name };
  });
  const baseRow = resolved.find(line => line.name.toUpperCase() === base.toUpperCase())?.row;
  const baseCost = numeric(hasValue(baseRow?.purchase_unit_price) ? baseRow.purchase_unit_price : material.purchase_unit_price, 'base cost');
  const rowPrice = hasValue(baseRow?.sales_unit_price) ? baseRow.sales_unit_price : baseRow?.sales_price_1;
  const basePrice = numeric(hasValue(rowPrice) ? rowPrice : material.sales_unit_price, 'base price');
  function defaultUom(field, legacy) {
    const selected = resolved.filter(line => flag(line.row[field], field) === true);
    if (selected.length > 1) throw new Error('Multiple ' + field + ' values');
    const name = selected.length ? selected[0].name : lookup(uoms, legacy, 'uom_name', field);
    if (name && name.toUpperCase() !== base.toUpperCase() && !resolved.some(line => line.name.toUpperCase() === name.toUpperCase())) throw new Error('Default UOM is not an item UOM');
    return name;
  }
  const item = {
    id: material.id, DOCKEY: material.item_uuid || '', CODE: sanitize(material.material_code),
    DESCRIPTION: sanitize(material.material_name), DESCRIPTION2: sanitize(material.material_desc),
    DESCRIPTION3: '', STOCKGROUP: sanitize(lookup(categories, material.item_category, 'mat_cat_code', 'item category') || 'DEFAULT'),
    SERIALNUMBER: 'F', MINQTY: '0', MAXQTY: '0', REORDERLEVEL: '0', REORDERQTY: '1', SUOM: '', ITEMTYPE: '-',
    LEADTIME: '0', BOM_LEADTIME: '0', BOM_ASMCOST: '0', STOCKMATRIX: '', SCRIPTCODE: '',
    ISACTIVE: Number(material.is_active) === 1 ? 'T' : 'F',
    BALSQTY: '0', BALSUOMQTY: '0', CREATIONDATE: text(material.created_at), PICTURE: '', PICTURECLASS: '',
    ATTACHMENTS: '', NOTE: '', LASTMODIFIED: text(material.updated_at), REMARK1: '', SHELF: '',
    DEFUOM_ST: base,
    uomLineItems: []
  };
  const stockControl = flag(material.stock_control, 'stock control');
  optional(item, 'STOCKCONTROL', stockControl === undefined ? undefined : stockControl ? 'T' : 'F');
  if (hasValue(material.material_costing_method)) {
    const costing = { 'Fixed Cost': '0', 'Weighted Average': '1', 'First In First Out': '2' }[material.material_costing_method];
    if (costing === undefined) throw new Error('Unknown costing method');
    item.COSTINGMETHOD = costing;
  }
  optional(item, 'SLTAX', lookup(taxes, material.mat_sales_tax_id, 'tax_code', 'sales tax'));
  optional(item, 'PHTAX', lookup(taxes, material.mat_purchase_tax_id, 'tax_code', 'purchase tax'));
  // SQL sync stores its single TARIFF in purchase_tariff_id.
  const purchaseTariff = lookup(tariffs, material.purchase_tariff_id, 'tariff_code', 'purchase tariff');
  const salesTariff = lookup(tariffs, material.sales_tariff_id, 'tariff_code', 'sales tariff');
  if (purchaseTariff && salesTariff && purchaseTariff !== salesTariff) throw new Error('SQL supports one tariff; purchase and sales tariffs differ');
  optional(item, 'TARIFF', purchaseTariff || salesTariff);
  if (hasValue(material.irbm_id)) item.IRBM_CLASSIFICATION = text(material.irbm_id);
  optional(item, 'DEFUOM_PH', defaultUom('purchase_default_uom', material.purchase_default_uom));
  optional(item, 'DEFUOM_SL', defaultUom('sales_default_uom', material.sales_default_uom));
  // Prices belong to cdsUOM. Do not depend on unsupported MainDataSet price fields.
  const baseLine = { UOM: base, ISBASE: 'True', RATE: '1' };
  optional(baseLine, 'REFCOST', baseCost); optional(baseLine, 'REFPRICE', basePrice);
  item.uomLineItems.push(baseLine);
  for (const { row, name } of resolved) {
    if (name.toUpperCase() === base.toUpperCase()) continue;
    const altQty = numeric(row.alt_qty, 'alternate quantity');
    const baseQty = numeric(row.base_qty, 'base quantity');
    if (!(altQty > 0) || !(baseQty > 0)) throw new Error('UOM conversion quantities must be positive');
    const line = { UOM: name, ISBASE: 'False', RATE: text(baseQty / altQty) };
    optional(line, 'REFCOST', numeric(row.purchase_unit_price, 'UOM cost'));
    optional(line, 'REFPRICE', numeric(hasValue(row.sales_unit_price) ? row.sales_unit_price : row.sales_price_1, 'UOM price'));
    item.uomLineItems.push(line);
  }
  const barcodeLines = [];
  const baseBarcode = barcode(hasValue(baseRow?.item_barcode) ? baseRow.item_barcode : material.barcode_number);
  if (baseBarcode !== undefined) barcodeLines.push({ UOM: base, BARCODE: baseBarcode });
  for (const { row, name } of resolved) {
    if (name.toUpperCase() === base.toUpperCase()) continue;
    const code = barcode(row.item_barcode);
    if (code !== undefined) barcodeLines.push({ UOM: name, BARCODE: code });
  }
  if (barcodeLines.length) item.barcodeLineItems = barcodeLines;
  // Price rows. Omitted when empty so existing accounting price rows are not erased.
  function sqlPriceLine(row, customerSide) {
    const r = resolvePriceRow(row, customerSide);
    const line = { SAAS_ROW_ID: r.rowId, TAGTYPE: customerSide ? 'C' : 'S', COMPANY: r.account || '', PRICETAG: r.tag || '', UOM: r.uom };
    optional(line, 'QTY', r.minQty);
    optional(line, 'STOCKVALUE', r.price);
    optional(line, 'DISCOUNT', r.discount);
    optional(line, 'DATEFROM', r.dateFrom);
    optional(line, 'DATETO', r.dateTo);
    return line;
  }
  const customerPriceLines = activePriceRows(material.table_customer_price).map(row => sqlPriceLine(row, true));
  const supplierPriceLines = activePriceRows(material.table_supplier_price).map(row => sqlPriceLine(row, false));
  if (customerPriceLines.length) item.customerPriceLineItems = customerPriceLines;
  if (supplierPriceLines.length) item.supplierPriceLineItems = supplierPriceLines;
  return item;
});

