// 1. Access the raw array from your node
let dataArray = {{node:search_node_AcNu48N8.data.data}};

// 2. Initialize an array to hold all names
let allItemNames = [];

if (Array.isArray(dataArray)) {
  dataArray.forEach(order => {
    // Check if the individual order has the table_so array
    if (order.table_so && Array.isArray(order.table_so)) {
      // Extract item_name from each sub-item and add to our list
      const names = order.table_so.map(subItem => subItem.item_name);
      allItemNames.push(...names);
    }
  });
}

// 3. Return the unique values
return {
  item_names: allItemNames.map((id) => ({ item_id: id })),
};

 // Fetch SO data safely
let rawData = {{node:search_node_AcNu48N8.data.data}} || [];
let dbSo = Array.isArray(rawData) ? rawData : (rawData ? [rawData] : []);

// Define reference tables for lookup with fallbacks
const dbTable = {
  customer: {{node:search_node_eIE6D77S.data.data}} || [],
  currency: {{node:search_node_DKERgSMT.data.data}} || [],
  state: {{node:search_node_U5d6157H.data.data}} || [],
  country: {{node:search_node_TDrBLLyh.data.data}} || [],
  uom: {{node:search_node_Aqb4dOgn.data.data}} || [],
  taxRatePercent: {{node:search_node_0u1kOrVb.data.data}} || [],
  taxRate: {{node:search_node_eTmcSB3V.data.data}} || [],
  item: {{node:search_node_fLQ3ydID.data.data}} || [],
  // item: {{node:search_node_AcNu48N8.data.data.table_so}} || [],
  agent: {{node:search_node_hWdJlw7B.data.data}} || [],
  paymentTerms: {{node:search_node_KTIjQHoa.data.data}} || []
};

// Helper function to safely convert values to strings
const safeString = (value) => {
  if (value === null || value === undefined) return "";
  if (typeof value === 'number') return String(value);
  if (typeof value === 'string') return value;
  try {
    return String(value);
  } catch (e) {
    console.error("Conversion error:", e);
    return "";
  }
};

// Helper function to sanitize strings (replace " with \u2033)
const sanitizeString = (value) => {
  const str = safeString(value);
  return str.replace(/"/g, '\u2033');
};

// Function to safely parse numeric values
const safeParseFloat = (value, defaultValue = 0) => {
  if (value === null || value === undefined) return defaultValue;
  if (typeof value === 'number') return value;
  try {
    const parsed = parseFloat(value);
    return isNaN(parsed) ? defaultValue : parsed;
  } catch (e) {
    console.error("Parse float error:", e);
    return defaultValue;
  }
};

// Format date safely (MM/DD/YYYY format)
// Format date safely (e.g. January 1, 2018)
const getFormattedDate = (date = null) => {
  try {
    const parsedDate = date ? new Date(date) : new Date();

    if (isNaN(parsedDate.getTime())) return "";

    const monthNames = [
      "January", "February", "March", "April", "May", "June",
      "July", "August", "September", "October", "November", "December"
    ];

    const month = monthNames[parsedDate.getMonth()];
    const day = parsedDate.getDate();
    const year = parsedDate.getFullYear();

    return sanitizeString(`${month} ${day}, ${year}`);
  } catch (e) {
    return "";
  }
};

// Function to normalize tax rate safely
const normalizeTaxRate = (taxRate) => {
  if (!taxRate) return "0%";
  try {
    const rateStr = safeString(taxRate).replace('%', '');
    const rateNum = parseFloat(rateStr);
    return isNaN(rateNum) ? "0%" : `${rateNum}%`;
  } catch (e) {
    console.error("Tax rate normalization error:", e);
    return "0%";
  }
};

// Lookup function with safe handling
const findCorrespondingProperty = (input, inputType, dbName, propertyName) => {
  if (input === null || input === undefined) return "";
  try {
    const collection = dbTable[dbName] || [];
    const findData = collection.find(data => String(data[inputType]) === String(input));
    return findData ? findData[propertyName] : "";
  } catch (e) {
    console.error("Lookup error:", e);
    return "";
  }
};

// Recursive sanitization for nested structures
const deepSanitize = (data) => {
  if (Array.isArray(data)) {
    return data.map(deepSanitize);
  }

  if (data && typeof data === 'object') {
    return Object.fromEntries(
      Object.entries(data).map(([key, value]) => [key, deepSanitize(value)])
    );
  }

  return sanitizeString(data);
};

// Main conversion function
const convertToInvoiceFormat = (inputArray) => {
  return inputArray.map(input => {
    const createTime = input.create_time || "";

    // Safely get line items
    const lineItems = Array.isArray(input.table_so) ? input.table_so : [];

    // Build main invoice object
    const invoice = {
      id: input.id,
      DOCNO: input.so_no || "",
      DOCNOEX: "",
      DOCDATE: getFormattedDate(input.so_date),
      POSTDATE: getFormattedDate(createTime),
      TAXDATE: "",
      EIVDATETIME: "",
      CODE: findCorrespondingProperty(input.customer_name, 'id', 'customer', 'customer_id'),
      COMPANYNAME: findCorrespondingProperty(input.customer_name, 'id', 'customer', 'customer_com_name'),
      ADDRESS1: input.billing_address_line_1 || "",
      ADDRESS2: input.billing_address_line_2 || "",
      ADDRESS3: input.billing_address_line_3 || "",
      ADDRESS4: input.billing_address_line_4 || "",
      POSTCODE: input.billing_postal_code || "",
      CITY: input.billing_address_city || "",
      STATE: findCorrespondingProperty(input.billing_address_state, 'id', 'state', 'state_name'),
      COUNTRY: findCorrespondingProperty(input.billing_address_country, 'id', 'country', 'country_code'),
      PHONE1: input.billing_address_phone || "",
      MOBILE: "",
      FAX1: "",
      ATTENTION: input.billing_attention || "",
      AREA: "",
      TERMS: findCorrespondingProperty(input.so_payment_term, 'id', 'paymentTerms', 'term_code'),
      CURRENCYCODE: input.currency_code || "",
      CURRENCYRATE: "",
      SHIPPER: "",
      DESCRIPTION: input.so_description || "Sales Order",
      CANCELLED: "False",
      DOCAMT: "",
      LOCALDOCAMT: "",
      LANDINGCOST1: "",
      LANDINGCOST2: "",
      LOCALTOTALWITHCOST: "",
      D_AMOUNT: "",
      VALIDITY: "",
      DELIVERYTERM: input.so_payment_details,
      CC: "",
      DOCREF1: input.so_remarks,
      DOCREF2: input.so_remarks2,
      DOCREF3: input.so_remarks3,
      DOCREF4: "",
      BRANCHNAME: input.shipping_address_name || "",
      DADDRESS1: input.shipping_address_line_1 || "",
      DADDRESS2: input.shipping_address_line_2 || "",
      DADDRESS3: input.shipping_address_line_3 || "",
      DADDRESS4: input.shipping_address_line_4 || "",
      DPOSTCODE: input.shipping_postal_code || "",
      DCITY: input.shipping_address_city || "",
      DSTATE: findCorrespondingProperty(input.shipping_address_state, 'id', 'state', 'state_name'),
      DCOUNTRY: findCorrespondingProperty(input.shipping_address_country, 'id', 'country', 'country_code'),
      DATTENTION: input.shipping_attention || "",
      DPHONE1: input.shipping_address_phone || "",
      DMOBILE: "",
      DFAX1: "",
      TAXEXEMPTNO: "",
      SALESTAXNO: "",
      SERVICETAXNO: "",
      TIN: "",
      IDTYPE: "",
      IDNO: "",
      TOURISMNO: "",
      SIC: "",
      INCOTERMS: "",
      SUBMISSIONTYPE: "",
      IRBM_STATUS: "",
      IRBM_INTERNALID: "",
      IRBM_UUID: "",
      IRBM_LONGID: "",
      ATTACHMENTS: "",
      NOTE: input.remarks || "",
      TRANSFERABLE: "",
      UPDATECOUNT: "",
      PRINTCOUNT: "",
      AGENT: findCorrespondingProperty(input.so_sales_person, 'id', 'agent', 'agent_code'),
      // SQL client side does not take paymentterm as input, need to add.
      PAYMENTTERM: findCorrespondingProperty(input.so_payment_term, 'id', 'paymentTerms', 'term_code'),
      LineItems: lineItems.map(item => {
        // Calculate amount safely
        const qty = safeParseFloat(item.so_quantity);
        const price = safeParseFloat(item.so_item_price);
        const amount = qty * price;
        const taxamount = safeParseFloat(item.so_tax_amount);

        return {
          QTY: safeString(qty),
          UOM: findCorrespondingProperty(item.so_item_uom, 'id', 'uom', 'uom_name'),
          TAXRATE: normalizeTaxRate(item.so_tax_percentage),

          ACCOUNT: "",
          TAX: findCorrespondingProperty(item.so_tax_preference, 'id', 'taxRate', 'tax_code'),
          TAXINCLUSIVE: item.so_tax_inclusive === 1 ? "true" : "false",
          AMOUNT: safeString(amount),
          DISC: safeString(safeParseFloat(item.so_discount_amount)),
          SUOMQTY: "",
          LOCALTAXAMT: "",
          LOCALAMOUNT: "",
          TAXAMT: safeString(taxamount),
          PRINTABLE: "",
          TRANSFERABLE: "",
          CHANGED: "",
          TAXABLEAMT: "",
          STYLEID: "",
          NUMBER: "",
          ITEMCODE: findCorrespondingProperty(item.item_name, 'id', 'item', 'material_code'),
          LOCATION: "",
          UNITPRICE: safeString(price),
          BATCH: "",
          PROJECT_1: "",
          DESCRIPTION_1: findCorrespondingProperty(item.item_name, 'id', 'item', 'material_name'),
          DESCRIPTION_2: item.so_desc || "",
          DESCRIPTION_3: item.more_desc || "",
          PERMITNO: "",
          DELIVERYDATE: item.so_shipping_date || "",
          TARIFF: "",
          TAXEXEMPTIONREASON: "",
          IRBM_CLASSIFICATION: "",
          IM_CURRENCYCODE: "",
          IM_CURRENCYRATE: "",
          IM_PURCHASEAMT: "",
          LANDINGCOST1_1: "",
          LANDINGCOST2_1: "",
          WHTAX: "",
          WHTAXRATE: "",
          WHLOCALTAXAMT: "",
          WHTAXACCOUNTDR: "",
          WHTAXACCOUNTCR: "",
          TRANSFERABLE_1: "",
          REMARK_1: item.line_remark_1 || "",
          REMARK_2: item.line_remark_2 || ""
        };
      })
    };

    return invoice;
  });
};

// Execute conversion with error handling
try {
  const result = convertToInvoiceFormat(dbSo);
  return deepSanitize(result);
} catch (error) {
  console.error("Conversion failed:", error);
  return [];
}

