      "July", "August", "September", "October", "November", "December"
    ];

    const month = monthNames[parsedDate.getMonth()];
    const day = parsedDate.getDate();
    const year = parsedDate.getFullYear();

    return sanitizeString(`${month} ${day}, ${year}`);
  } catch (e) {
