function isNullLike(value) {
  return (
    value === null ||
    value === undefined ||
    (typeof value === "string" && value.trim() === "")
  );
}

function safeString(value) {
  if (isNullLike(value)) {
    return "";
  }

  try {
    return String(value);
  } catch (error) {
    console.error("String conversion error:", error);
    return "";
  }
}

function sanitizeString(value) {
  return safeString(value).replace(/"/g, "\u2033");
}

function safeParseFloat(value, defaultValue = 0) {
  if (isNullLike(value)) {
    return defaultValue;
  }

  if (typeof value === "number") {
    return Number.isFinite(value) ? value : defaultValue;
  }

  try {
    const parsed = parseFloat(value);

    return Number.isFinite(parsed)
      ? parsed
      : defaultValue;
  } catch (error) {
    console.error("Number conversion error:", error);
    return defaultValue;
  }
}

function roundNumber(value, decimalPlaces = 4) {
  const number = safeParseFloat(value, 0);
  const multiplier = Math.pow(10, decimalPlaces);

  return (
    Math.round(
      (number + Number.EPSILON) * multiplier
    ) / multiplier
  );
}

function normalizeArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  return value ? [value] : [];
}

function normalizeSqlCode(value, fallback = "----") {
  const text = safeString(value).trim();

  if (!text || text === "----") {
    return fallback;
  }

  return text;
}

function isTrue(value) {
  if (value === true || value === 1) {
    return true;
  }

  const normalized = safeString(value)
    .trim()
    .toLowerCase();

  return (
    normalized === "true" ||
    normalized === "1" ||
    normalized === "t" ||
    normalized === "yes"
  );
}


// ============================================================================
// 3. DATE HELPERS
// ============================================================================

// SQL client date format, for example: July 14, 2026
function getFormattedDate(value = null) {
  if (isNullLike(value)) {
    return "";
  }

  try {
    const originalValue = safeString(value).trim();

    /*
     * SaaS dates normally look like:
     * 2026-07-14 00:00:00
     *
     * Since there is no timezone indicator, preserve the date portion directly
     * to avoid server timezone conversion changing the date.
     */
    const localDateMatch = originalValue.match(
      /^(\d{4})-(\d{2})-(\d{2})(?:\s|$)/
    );

    if (
      localDateMatch &&
      !originalValue.endsWith("Z") &&
      !/[+-]\d{2}:\d{2}$/.test(originalValue)
    ) {
      const year = Number(localDateMatch[1]);
      const month = Number(localDateMatch[2]);
      const day = Number(localDateMatch[3]);

      return formatDateParts(year, month, day);
    }

    const parsedDate = new Date(originalValue);

    if (isNaN(parsedDate.getTime())) {
      return "";
    }

    // Convert timezone-aware dates into Malaysia time
    const dateParts = new Intl.DateTimeFormat("en-US", {
      timeZone: "Asia/Kuala_Lumpur",
      year: "numeric",
      month: "numeric",
      day: "numeric"
    }).formatToParts(parsedDate);

    const year = Number(
      dateParts.find(part => part.type === "year")?.value
    );

    const month = Number(
      dateParts.find(part => part.type === "month")?.value
    );

    const day = Number(
      dateParts.find(part => part.type === "day")?.value
    );

    return formatDateParts(year, month, day);
  } catch (error) {
    console.error("Date conversion error:", error);
    return "";
  }
}

function formatDateParts(year, month, day) {
  const monthNames = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December"
  ];

  if (
    !Number.isFinite(year) ||
    !Number.isFinite(month) ||
    !Number.isFinite(day) ||
    month < 1 ||
    month > 12
  ) {
    return "";
  }

  return sanitizeString(
    `${monthNames[month - 1]} ${day}, ${year}`
  );
}


// ============================================================================
// 4. LOOKUP HELPERS
// ============================================================================

function findCorrespondingRecord(input, inputType, dbName) {
  if (isNullLike(input)) {
    return null;
  }

  try {
    const collection = normalizeArray(dbTable[dbName]);

    return collection.find(row =>
      safeString(row?.[inputType]).trim() ===
      safeString(input).trim()
    ) || null;
  } catch (error) {
    console.error(`Lookup error for ${dbName}:`, error);
    return null;
  }
}

function findCorrespondingProperty(
  input,
  inputType,
  dbName,
  propertyName,
  defaultValue = ""
) {
  const matchedRecord = findCorrespondingRecord(
    input,
    inputType,
    dbName
  );

  if (
    !matchedRecord ||
    isNullLike(matchedRecord[propertyName])
  ) {
    return defaultValue;
  }

  return matchedRecord[propertyName];
}


// ============================================================================
// 5. TAX AND DISCOUNT HELPERS
// ============================================================================

function normalizeTaxRate(taxRate) {
  if (isNullLike(taxRate)) {
    return "0%";
  }

  try {
    const rateText = safeString(taxRate)
      .replace(/%/g, "")
      .trim();

    const rateNumber = safeParseFloat(rateText, 0);

    return `${rateNumber}%`;
  } catch (error) {
    console.error(
      "Tax rate normalization error:",
      error
    );

    return "0%";
  }
}

function getTaxRatePercent(item) {
  const rawTaxRate = safeString(
    item?.so_tax_percentage
  )
    .replace(/%/g, "")
    .trim();

  return safeParseFloat(rawTaxRate, 0);
}

function buildDiscountValue(item) {
  const discountUom = safeString(
    item?.so_discount_uom
  )
    .trim()
    .toLowerCase();

  const discountValue = safeParseFloat(
    item?.so_discount,
    0
  );

  const discountAmount = safeParseFloat(
    item?.so_discount_amount,
    0
  );

  if (
    discountUom === "%" ||
    discountUom === "percent" ||
    discountUom === "percentage"
  ) {
    return `${discountValue}%`;
  }

  if (
    discountUom === "amount" ||
    discountUom === "amt" ||
    discountUom === "rm"
  ) {
    return safeString(
      roundNumber(discountAmount, 4)
    );
  }

  /*
   * Fallback:
   * If so_discount contains a value, use it.
   * Otherwise use the calculated discount amount.
   */
  if (discountValue !== 0) {
    return safeString(
      roundNumber(discountValue, 4)
    );
  }

  return safeString(
    roundNumber(discountAmount, 4)
  );
}


// ============================================================================
// 6. LINE CALCULATION
// ============================================================================

function calculateLineValues(item, exchangeRate) {
  const qty = safeParseFloat(
    item?.so_quantity,
    0
  );

  const unitPrice = safeParseFloat(
    item?.so_item_price,
    0
  );

  const calculatedGross = qty * unitPrice;

  const suppliedGross = safeParseFloat(
    item?.so_gross,
    NaN
  );

  /*
   * so_gross should normally be the gross amount before discount.
   *
   * Fall back to:
   * quantity × unit price
   */
  const gross = Number.isFinite(suppliedGross)
    ? suppliedGross
    : calculatedGross;

  const discountAmount = safeParseFloat(
    item?.so_discount_amount,
    0
  );

  const suppliedTaxAmount = safeParseFloat(
    item?.so_tax_amount,
    0
  );

  const suppliedTotalAmount = safeParseFloat(
    item?.so_amount,
    NaN
  );

  const taxInclusive = isTrue(
    item?.so_tax_inclusive
  );

  const taxRatePercent = getTaxRatePercent(item);

  /*
   * Amount after discount.
   *
   * Example:
   * Quantity       = 16
   * Unit price     = 100
   * Gross          = 1600
   * Discount       = 160
   * After discount = 1440
   */
  let discountedAmount =
    gross - discountAmount;

  if (Math.abs(discountedAmount) < 0.000001) {
    discountedAmount = 0;
  }

  let amountExcludingTax;
  let taxAmount;

  if (taxInclusive) {
    /*
     * TAX-INCLUSIVE CALCULATION
     *
     * The discounted amount already includes tax.
     *
     * Example:
     * Discounted amount = 1440
     * Tax rate          = 10%
     *
     * Exclusive amount:
     * 1440 / 1.10 = 1309.0909
     *
     * Tax:
     * 1440 - 1309.0909 = 130.9091
     *
     * SQL result:
     * AMOUNT   = 1309.09
     * TAXAMT   = 130.91
     * Total    = 1440.00
     */
    if (taxRatePercent > 0) {
      amountExcludingTax =
        discountedAmount /
        (1 + taxRatePercent / 100);

      taxAmount =
        discountedAmount -
        amountExcludingTax;
    } else {
      amountExcludingTax =
        discountedAmount;

      taxAmount = 0;
    }
  } else {
    /*
     * TAX-EXCLUSIVE CALCULATION
     *
     * SaaS so_amount normally contains the final amount including tax.
     *
     * Example:
     * Gross after discount = 945.00
     * Tax                  = 47.25
     * SaaS so_amount       = 992.25
     *
     * SQL AMOUNT:
     * 992.25 - 47.25 = 945.00
     */
    taxAmount = suppliedTaxAmount;

    if (Number.isFinite(suppliedTotalAmount)) {
      amountExcludingTax =
        suppliedTotalAmount -
        taxAmount;
    } else {
      amountExcludingTax =
        discountedAmount;
    }
  }

  // Prevent small floating-point values such as -0.0000001
  if (Math.abs(amountExcludingTax) < 0.000001) {
    amountExcludingTax = 0;
  }

  if (Math.abs(taxAmount) < 0.000001) {
    taxAmount = 0;
  }

  const localAmount =
    amountExcludingTax * exchangeRate;

  const localTaxAmount =
    taxAmount * exchangeRate;

  return {
    qty: roundNumber(qty, 3),

    unitPrice: roundNumber(
      unitPrice,
      4
    ),

    gross: roundNumber(
      gross,
      4
    ),

    discountAmount: roundNumber(
      discountAmount,
      4
    ),

    taxAmount: roundNumber(
      taxAmount,
      4
    ),

    amountExcludingTax: roundNumber(
      amountExcludingTax,
      4
    ),

    localAmount: roundNumber(
      localAmount,
      4
    ),

    localTaxAmount: roundNumber(
      localTaxAmount,
      4
    )
  };
}


// ============================================================================
// 7. HEADER TOTAL HELPERS
// ============================================================================

function calculateHeaderTotals(input, lineItems) {
  const exchangeRate = safeParseFloat(
    input?.exchange_rate,
    1
  ) || 1;

  const calculatedTotal = lineItems.reduce(
    (total, item) => {
      return total + safeParseFloat(
        item?.so_amount,
        0
      );
    },
    0
  );

  const calculatedTax = lineItems.reduce(
    (total, item) => {
      return total + safeParseFloat(
        item?.so_tax_amount,
        0
      );
    },
    0
  );

  const calculatedGross = lineItems.reduce(
    (total, item) => {
      const qty = safeParseFloat(
        item?.so_quantity,
        0
      );

      const unitPrice = safeParseFloat(
        item?.so_item_price,
        0
      );

      return total + safeParseFloat(
        item?.so_gross,
        qty * unitPrice
      );
    },
    0
  );

  const calculatedDiscount = lineItems.reduce(
    (total, item) => {
      return total + safeParseFloat(
        item?.so_discount_amount,
        0
      );
    },
    0
  );

  const documentAmount = isNullLike(input?.so_total)
    ? calculatedTotal
    : safeParseFloat(
        input.so_total,
        calculatedTotal
      );

  const localDocumentAmount = isNullLike(
    input?.myr_total_amount
  )
    ? documentAmount * exchangeRate
    : safeParseFloat(
        input.myr_total_amount,
        documentAmount * exchangeRate
      );

  return {
    exchangeRate: roundNumber(
      exchangeRate,
      6
    ),

    grossAmount: roundNumber(
      isNullLike(input?.so_total_gross)
        ? calculatedGross
        : input.so_total_gross,
      4
    ),

    discountAmount: roundNumber(
      isNullLike(input?.so_total_discount)
        ? calculatedDiscount
        : input.so_total_discount,
      4
    ),

    taxAmount: roundNumber(
      isNullLike(input?.so_total_tax)
        ? calculatedTax
        : input.so_total_tax,
      4
    ),

    documentAmount: roundNumber(
      documentAmount,
      4
    ),

    localDocumentAmount: roundNumber(
      localDocumentAmount,
      4
    )
  };
}


// ============================================================================
// 8. PAYMENT HELPERS
// ============================================================================

function getPaymentMethod(input) {
  /*
   * Prefer dedicated fields when they are available.
   * Fall back to so_payment_details because the supplied SaaS structure
   * currently does not show a dedicated payment-method field.
   */
  return safeString(
    input?.payment_method_code ||
    input?.so_payment_method_code ||
    input?.so_payment_method ||
    input?.so_payment_details ||
    ""
  ).trim();
}

function getChequeNumber(input) {
  return safeString(
    input?.cheque_number ||
    input?.payment_cheque_number ||
    input?.so_cheque_number ||
    ""
  ).trim();
}

function getBankCharge(input) {
  return roundNumber(
    input?.bank_charge ||
    input?.payment_bank_charge ||
    0,
    4
  );
}

function getBankChargeAccount(input) {
  return safeString(
    input?.bank_charge_account ||
    input?.payment_bank_charge_account ||
    ""
  ).trim();
}


// ============================================================================
// 9. RECURSIVE OUTPUT SANITIZATION
// ============================================================================

function deepSanitize(data) {
  if (Array.isArray(data)) {
    return data.map(deepSanitize);
  }

  if (data && typeof data === "object") {
    return Object.fromEntries(
      Object.entries(data).map(([key, value]) => [
        key,
        deepSanitize(value)
      ])
    );
  }

  return sanitizeString(data);
}


// ============================================================================
// 10. MAIN CASH SALES CONVERSION
// ============================================================================

function convertToCashSalesFormat(inputArray) {
  return normalizeArray(inputArray)

    // Only process Cash Sales records
    .filter(input => {
      const soType = safeString(input?.so_type)
        .trim()
        .toLowerCase();

      /*
       * Include rows where so_type is empty for backward compatibility.
       * Exclude rows explicitly marked as another Sales Order type.
       */
      return !soType || soType === "cash";
    })

    .map(input => {
      const lineItems = normalizeArray(
        input?.table_so
      );

      const totals = calculateHeaderTotals(
        input,
        lineItems
      );

      const customerRecord = findCorrespondingRecord(
        input?.customer_name,
        "id",
        "customer"
      );

      const customerCode =
        customerRecord?.customer_id ||
        customerRecord?.customer_code ||
        customerRecord?.acc_no ||
        "";

      const customerName =
        customerRecord?.customer_com_name ||
        "";

      const areaCode =
        input?.so_area_code ||
        customerRecord?.area_code ||
        "----";

      const paymentMethod =
        getPaymentMethod(input);

      const chequeNumber =
        getChequeNumber(input);

      const bankCharge =
        getBankCharge(input);

      const bankChargeAccount =
        getBankChargeAccount(input);

      const documentNumber =
        safeString(input?.so_no);

      const isCancelled =
        safeString(input?.so_status)
          .trim()
          .toLowerCase() === "cancelled";

      const currencyCode = normalizeSqlCode(
        input?.so_currency ||
        input?.currency_code,
        "----"
      );

      const deliveryMethod = normalizeSqlCode(
        input?.delivery_method_text ||
        input?.so_delivery_method,
        "----"
      );

      const paymentAmount =
        totals.documentAmount;

      return {
        // SaaS source record ID
        id: input?.id || "",

        // --------------------------------------------------------------------
        // SL_CS HEADER
        // --------------------------------------------------------------------

        DOCNO: documentNumber,

        DOCNOEX:
          input?.so_docno ||
          input?.so_ref_doc ||
          "",

        DOCDATE: getFormattedDate(
          input?.so_date
        ),

        POSTDATE: getFormattedDate(
          input?.create_time ||
          input?.so_date
        ),

        TAXDATE: getFormattedDate(
          input?.so_date
        ),

        EIV_UTC: "",
        EIV_RECEIVED_UTC: "",
        EIV_VALIDATED_UTC: "",

        CODE: customerCode,

        COMPANYNAME: customerName,

        ADDRESS1:
          input?.billing_address_line_1 ||
          "",

        ADDRESS2:
          input?.billing_address_line_2 ||
          "",

        ADDRESS3:
          input?.billing_address_line_3 ||
          "",

        ADDRESS4:
          input?.billing_address_line_4 ||
          "",

        POSTCODE:
          input?.billing_postal_code ||
          "",

        CITY:
          input?.billing_address_city ||
          "",

        STATE: findCorrespondingProperty(
          input?.billing_address_state,
          "id",
          "state",
          "state_name"
        ),

        COUNTRY: findCorrespondingProperty(
          input?.billing_address_country,
          "id",
          "country",
          "country_code"
        ),

        PHONE1:
          input?.billing_address_phone ||
          "",

        MOBILE: "",

        FAX1:
          input?.billing_address_fax ||
          "",

        ATTENTION:
          input?.billing_attention ||
          "",

        AREA: normalizeSqlCode(
          areaCode,
          "----"
        ),

        AGENT: findCorrespondingProperty(
          input?.so_sales_person,
          "id",
          "agent",
          "agent_code"
        ),

        PROJECT: "----",

        TERMS: findCorrespondingProperty(
          input?.so_payment_term,
          "id",
          "paymentTerms",
          "term_code"
        ),

        CURRENCYCODE: currencyCode,

        CURRENCYRATE:
          totals.exchangeRate,

        SHIPPER: deliveryMethod,

        DESCRIPTION:
          input?.so_description ||
          "Cash Sales",

        CANCELLED: isCancelled
          ? "True"
          : "False",

        STATUS: isCancelled
          ? 1
          : 0,

        DOCAMT:
          totals.documentAmount,

        LOCALDOCAMT:
          totals.localDocumentAmount,

        /*
         * D_AMOUNT is not the line discount total.
         * The SQL Cash Sales sample keeps this as zero.
         */
        D_AMOUNT: 0,

        // --------------------------------------------------------------------
        // CASH SALES PAYMENT FIELDS
        // --------------------------------------------------------------------

        P_DOCNO: documentNumber,

        P_PAYMENTMETHOD:
          paymentMethod,

        P_CHEQUENUMBER:
          chequeNumber,

        P_PAYMENTPROJECT:
          "----",

        P_BANKCHARGE:
          bankCharge,

        P_BANKCHARGEACCOUNT:
          bankChargeAccount,

        P_AMOUNT:
          paymentAmount,

        P_PAIDAMOUNT:
          paymentAmount,

        // --------------------------------------------------------------------
        // DELIVERY / REFERENCE FIELDS
        // --------------------------------------------------------------------

        VALIDITY:
          input?.validity_of_collection ||
          "",

        DELIVERYTERM:
          input?.so_delivery_term ||
          "",

        CC: "",

        DOCREF1:
          input?.so_remarks ||
          "",

        DOCREF2:
          input?.so_remarks2 ||
          "",

        DOCREF3:
          input?.so_remarks3 ||
          "",

        DOCREF4:
          input?.so_remarks4 ||
          "",

        BRANCHNAME:
          input?.shipping_address_name ||
          "DELIVERY",

        DADDRESS1:
          input?.shipping_address_line_1 ||
          "",

        DADDRESS2:
          input?.shipping_address_line_2 ||
          "",

        DADDRESS3:
          input?.shipping_address_line_3 ||
          "",

        DADDRESS4:
          input?.shipping_address_line_4 ||
          "",

        DPOSTCODE:
          input?.shipping_postal_code ||
          "",

        DCITY:
          input?.shipping_address_city ||
          "",

        DSTATE: findCorrespondingProperty(
          input?.shipping_address_state,
          "id",
          "state",
          "state_name"
        ),

        DCOUNTRY: findCorrespondingProperty(
          input?.shipping_address_country,
          "id",
          "country",
          "country_code"
        ),

        DATTENTION:
          input?.shipping_attention ||
          "",

        DPHONE1:
          input?.shipping_address_phone ||
          "",

        DMOBILE: "",

        DFAX1:
          input?.shipping_address_fax ||
          "",

        // --------------------------------------------------------------------
        // TAX / E-INVOICE INFORMATION
        // --------------------------------------------------------------------

        TAXEXEMPTNO: "",
        SALESTAXNO: "",
        SERVICETAXNO: "",
        TIN: "",
        IDTYPE: "",
        IDNO: "",
        TOURISMNO: "",
        SIC: "",
        INCOTERMS: "",

        SUBMISSIONTYPE: "",
        IRBM_STATUS: "",
        IRBM_INTERNALID: "",
        IRBM_UUID: "",
        IRBM_LONGID: "",

        EIVREQUEST_UUID: "",
        PEPPOL_UUID: "",
        PEPPOL_DOCUUID: "",

        BUSINESSUNIT: "",
        ATTACHMENTS: "",
        NOTE:
          input?.so_remarks5 ||
          "",

        APPROVESTATE: "",

        TRANSFERABLE: "True",
        UPDATECOUNT: "",
        PRINTCOUNT: 0,

        /*
         * Retained because the current SQL client mapping expects
         * PAYMENTTERM separately from TERMS.
         */
        PAYMENTTERM: findCorrespondingProperty(
          input?.so_payment_term,
          "id",
          "paymentTerms",
          "term_code"
        ),

        // --------------------------------------------------------------------
        // SL_CSDTL DETAIL
        // --------------------------------------------------------------------

        LineItems: lineItems.map(
          (item, index) => {
            const calculation =
              calculateLineValues(
                item,
                totals.exchangeRate
              );

            const packingConversion =
              safeParseFloat(
                item?.packing_conversion,
                1
              ) || 1;

            const sequence =
              !isNullLike(item?.line_index)
                ? safeParseFloat(
                    item.line_index,
                    (index + 1) * 1000
                  )
                : (index + 1) * 1000;

            const itemCode =
              findCorrespondingProperty(
                item?.item_name,
                "id",
                "item",
                "material_code"
              );

            const uomName =
              findCorrespondingProperty(
                item?.so_item_uom,
                "id",
                "uom",
                "uom_name"
              );

            const taxCode =
              findCorrespondingProperty(
                item?.so_tax_preference,
                "id",
                "taxRate",
                "tax_code"
              );

            return {
              SEQ: sequence,

              STYLEID: "",
              NUMBER: "",

              ITEMCODE: itemCode,

              LOCATION: "----",
              BATCH: "",
              PROJECT_1: "----",

              DESCRIPTION_1:
                item?.item_id ||
                "",

              DESCRIPTION_2:
                item?.so_desc ||
                "",

              DESCRIPTION_3:
                item?.more_desc ||
                item?.further_description ||
                "",

              PERMITNO: "",

              QTY:
                calculation.qty,

              UOM:
                uomName,

              RATE: roundNumber(
                packingConversion,
                4
              ),

              SQTY: roundNumber(
                calculation.qty *
                packingConversion,
                3
              ),

              SUOMQTY: 0,

              UNITPRICE:
                calculation.unitPrice,

              DELIVERYDATE:
                getFormattedDate(
                  item?.delivery_date ||
                  input?.so_shipping_date ||
                  input?.cs_shipping_date ||
                  input?.so_date
                ),

              DISC:
                buildDiscountValue(item),

              TAX:
                taxCode,

              TARIFF: "",

              TAXEXEMPTIONREASON: "",

              IRBM_CLASSIFICATION: "",

              TAXRATE:
                normalizeTaxRate(
                  item?.so_tax_percentage
                ),

              TAXAMT:
                calculation.taxAmount,

              LOCALTAXAMT:
                calculation.localTaxAmount,

              EXEMPTED_TAXRATE: "",
              EXEMPTED_TAXAMT: 0,

              TAXINCLUSIVE:
                isTrue(
                  item?.so_tax_inclusive
                )
                  ? "true"
                  : "false",

              /*
               * Tax-exclusive:
               * AMOUNT = supplied final amount - supplied tax.
               *
               * Tax-inclusive:
               * AMOUNT = discounted gross / (1 + tax rate).
               */
              AMOUNT:
                calculation.amountExcludingTax,

              LOCALAMOUNT:
                calculation.localAmount,

              TAXABLEAMT:
                calculation.amountExcludingTax,

              PRINTABLE: "true",

              ACCOUNT: "",

              FROMDOCTYPE: "",
              FROMDOCKEY: "",
              FROMDTLKEY: "",

              TRANSFERABLE: "true",

              REMARK_1:
                item?.line_remark_1 ||
                "",

              REMARK_2:
                item?.line_remark_2 ||
                "",

              INITIALPURCHASECOST: 0,

              // Retained fields from the reference post script
              CHANGED: "",
